// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SetHomeCountries Replace the Home Countries (at most three)
	// (PUT /account/home-countries)
	SetHomeCountries(ctx context.Context, request SetHomeCountriesRequestObject) (SetHomeCountriesResponseObject, error)
	// GetLimits The quotas in force, read only
	// (GET /account/limits)
	GetLimits(ctx context.Context, request GetLimitsRequestObject) (GetLimitsResponseObject, error)
	// SetPasskeyEnforcement Turn Enforce Passkey on or off
	// (PUT /account/passkey-enforcement)
	SetPasskeyEnforcement(ctx context.Context, request SetPasskeyEnforcementRequestObject) (SetPasskeyEnforcementResponseObject, error)
	// ListPasskeys The user's passkeys, stale ones included
	// (GET /account/passkeys)
	ListPasskeys(ctx context.Context, request ListPasskeysRequestObject) (ListPasskeysResponseObject, error)
	// PasskeyBegin Start adding a passkey
	// (POST /account/passkeys/begin)
	PasskeyBegin(ctx context.Context, request PasskeyBeginRequestObject) (PasskeyBeginResponseObject, error)
	// PasskeyFinish Finish adding a passkey with the browser's attestation
	// (POST /account/passkeys/finish)
	PasskeyFinish(ctx context.Context, request PasskeyFinishRequestObject) (PasskeyFinishResponseObject, error)
	// ReviewPasskeys Confirm the passkey list after a recovery
	// (POST /account/passkeys/review)
	ReviewPasskeys(ctx context.Context, request ReviewPasskeysRequestObject) (ReviewPasskeysResponseObject, error)
	// DeletePasskey Delete a passkey
	// (DELETE /account/passkeys/{id})
	DeletePasskey(ctx context.Context, request DeletePasskeyRequestObject) (DeletePasskeyResponseObject, error)
	// RenamePasskey Rename a passkey
	// (PATCH /account/passkeys/{id})
	RenamePasskey(ctx context.Context, request RenamePasskeyRequestObject) (RenamePasskeyResponseObject, error)
	// ChangePassword Set a new password
	// (POST /account/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// StartPhoneChange Start a phone change; a code goes to both numbers
	// (POST /account/phone/change)
	StartPhoneChange(ctx context.Context, request StartPhoneChangeRequestObject) (StartPhoneChangeResponseObject, error)
	// ConfirmPhoneChange Finish a phone change with both codes
	// (POST /account/phone/change/{id}/confirm)
	ConfirmPhoneChange(ctx context.Context, request ConfirmPhoneChangeRequestObject) (ConfirmPhoneChangeResponseObject, error)
	// UpdatePreferences Language, theme and the onboarding checklist
	// (PATCH /account/preferences)
	UpdatePreferences(ctx context.Context, request UpdatePreferencesRequestObject) (UpdatePreferencesResponseObject, error)
	// ListSessions The user's live sessions
	// (GET /account/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// DeleteSession End another session
	// (DELETE /account/sessions/{id})
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// TotpConfirm Prove the app has the secret and turn TOTP on
	// (POST /account/totp/confirm)
	TotpConfirm(ctx context.Context, request TotpConfirmRequestObject) (TotpConfirmResponseObject, error)
	// TotpDisable Turn TOTP off
	// (POST /account/totp/disable)
	TotpDisable(ctx context.Context, request TotpDisableRequestObject) (TotpDisableResponseObject, error)
	// RegenerateRecoveryCodes Replace the recovery codes
	// (POST /account/totp/recovery-codes)
	RegenerateRecoveryCodes(ctx context.Context, request RegenerateRecoveryCodesRequestObject) (RegenerateRecoveryCodesResponseObject, error)
	// TotpSetup Make a TOTP secret, not yet enabled
	// (POST /account/totp/setup)
	TotpSetup(ctx context.Context, request TotpSetupRequestObject) (TotpSetupResponseObject, error)
	// ListAnnouncements The announcements addressed to this tenant
	// (GET /announcements)
	ListAnnouncements(ctx context.Context, request ListAnnouncementsRequestObject) (ListAnnouncementsResponseObject, error)
	// ReadAnnouncement Mark an announcement read
	// (POST /announcements/{id}/read)
	ReadAnnouncement(ctx context.Context, request ReadAnnouncementRequestObject) (ReadAnnouncementResponseObject, error)
	// GetAuthConfig What the login page needs before anyone is signed in
	// (GET /auth/config)
	GetAuthConfig(ctx context.Context, request GetAuthConfigRequestObject) (GetAuthConfigResponseObject, error)
	// LookupInvite Read an invite link, for the invite page
	// (POST /auth/invites/lookup)
	LookupInvite(ctx context.Context, request LookupInviteRequestObject) (LookupInviteResponseObject, error)
	// LoginOtp Sign in with a code sent by SMS
	// (POST /auth/login/otp)
	LoginOtp(ctx context.Context, request LoginOtpRequestObject) (LoginOtpResponseObject, error)
	// LoginPassword Sign in with a phone number and a password
	// (POST /auth/login/password)
	LoginPassword(ctx context.Context, request LoginPasswordRequestObject) (LoginPasswordResponseObject, error)
	// LoginTotp Finish a login with a TOTP code or a recovery code
	// (POST /auth/login/totp)
	LoginTotp(ctx context.Context, request LoginTotpRequestObject) (LoginTotpResponseObject, error)
	// Logout End this session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// LogoutAll End every session of this user, this one included
	// (POST /auth/logout-all)
	LogoutAll(ctx context.Context, request LogoutAllRequestObject) (LogoutAllResponseObject, error)
	// RequestOtp Send a code by SMS for login, signup, Forgot Password or an invite
	// (POST /auth/otp/request)
	RequestOtp(ctx context.Context, request RequestOtpRequestObject) (RequestOtpResponseObject, error)
	// PasskeyLoginBegin Start a discoverable Passkey login
	// (POST /auth/passkey/login/begin)
	PasskeyLoginBegin(ctx context.Context, request PasskeyLoginBeginRequestObject) (PasskeyLoginBeginResponseObject, error)
	// PasskeyLoginFinish Finish a Passkey login with the browser's assertion
	// (POST /auth/passkey/login/finish)
	PasskeyLoginFinish(ctx context.Context, request PasskeyLoginFinishRequestObject) (PasskeyLoginFinishResponseObject, error)
	// ResetComplete Set a new password
	// (POST /auth/password/reset/complete)
	ResetComplete(ctx context.Context, request ResetCompleteRequestObject) (ResetCompleteResponseObject, error)
	// ResetPasskeyBegin Start the Passkey proof of Forgot Password
	// (POST /auth/password/reset/passkey/begin)
	ResetPasskeyBegin(ctx context.Context, request ResetPasskeyBeginRequestObject) (ResetPasskeyBeginResponseObject, error)
	// ResetPasskeyFinish Finish the Passkey proof of Forgot Password
	// (POST /auth/password/reset/passkey/finish)
	ResetPasskeyFinish(ctx context.Context, request ResetPasskeyFinishRequestObject) (ResetPasskeyFinishResponseObject, error)
	// ResetVerify Check the Forgot Password code and say what else is needed
	// (POST /auth/password/reset/verify)
	ResetVerify(ctx context.Context, request ResetVerifyRequestObject) (ResetVerifyResponseObject, error)
	// Reauth Prove the current factors again and open a ten minute reauth window
	// (POST /auth/reauth)
	Reauth(ctx context.Context, request ReauthRequestObject) (ReauthResponseObject, error)
	// ReauthOtpRequest Send a reauth code to the signed-in user's own number
	// (POST /auth/reauth/otp/request)
	ReauthOtpRequest(ctx context.Context, request ReauthOtpRequestRequestObject) (ReauthOtpRequestResponseObject, error)
	// ReauthPasskeyBegin Start a Passkey assertion for the signed-in user
	// (POST /auth/reauth/passkey/begin)
	ReauthPasskeyBegin(ctx context.Context, request ReauthPasskeyBeginRequestObject) (ReauthPasskeyBeginResponseObject, error)
	// ReauthPasskeyFinish Finish a Passkey reauth
	// (POST /auth/reauth/passkey/finish)
	ReauthPasskeyFinish(ctx context.Context, request ReauthPasskeyFinishRequestObject) (ReauthPasskeyFinishResponseObject, error)
	// RefreshSession Renew the session from the refresh cookie
	// (POST /auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// Register Create an account with an SMS code, in open mode or with an invite
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// GetMe The shell's bootstrap
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListNotifications The bell
	// (GET /notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// ReadNotification Mark a notification read
	// (POST /notifications/{id}/read)
	ReadNotification(ctx context.Context, request ReadNotificationRequestObject) (ReadNotificationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

